const categories = [
  { name: '한국 현대소설', count: 2000 },
  { name: '한국 고전소설', count: 300 },
  { name: '영미 문학', count: 1500 },
  { name: '일본 문학', count: 1000 },
  { name: '프랑스 문학', count: 500 },
  { name: '독일 문학', count: 400 },
  { name: '러시아 문학', count: 500 },
  { name: '중남미 문학', count: 300 },
  { name: '중국 문학', count: 300 },
  { name: '기타 세계문학', count: 200 },
  { name: 'SF', count: 500 },
  { name: '미스터리/스릴러', count: 600 },
  { name: '판타지', count: 500 },
  { name: '로맨스', count: 500 },
  { name: '역사소설', count: 400 },
  { name: '성장소설', count: 300 },
  { name: '공포/호러', count: 200 }
];

const chunkSize = 5;
const batches = [];

for (const cat of categories) {
  const totalBatches = Math.ceil(cat.count / chunkSize);
  for (let i = 0; i < totalBatches; i++) {
    batches.push({
      json: {
        category: cat.name,
        batchIndex: i + 1,
        batchSize: chunkSize,
        totalBatches,
      },
    });
  }
}

return batches;

const batch = $('배치 순회').item.json;
const currentItems = $input.all();

const existing = currentItems.length > 0 && currentItems[0].json.title
  ? currentItems.map(item => `${item.json.title} - ${item.json.author}`).slice(0, 10)
  : [];

const excludeList = existing.length > 0 ? existing.join(', ') : '없음';

const prompt = `다음 조건을 만족하는 ${batch.category} 소설 ${batch.batchSize}권을 골라 각 작품당 한국어 명문장 1개씩만 반환하세요.

조건:
- 실제 존재하는 소설만 사용
- 한국어 원서 또는 한국어 번역 출간본만 사용
- 서로 다른 책만 선택
- 이미 있는 책은 제외: ${excludeList}
- 설명, 해설, 코드블록 없이 JSON 배열만 출력

출력 형식:
[{"title":"책 제목","author":"저자명","quote":"명문장"}]`;

return [{
  json: {
    ...batch,
    prompt,
  }
}];

const response = $input.first().json;
const batch = $('수집 프롬프트 생성').item.json;

const text = response?.choices?.[0]?.message?.content;
if (!text) {
  throw new Error('Groq 명문장 추출 응답 오류: ' + JSON.stringify(response).slice(0, 500));
}

const extractJSONArray = (source) => {
  const cleaned = source.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('[');
  const end = cleaned.lastIndexOf(']');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('JSON 배열을 찾지 못했습니다: ' + cleaned.substring(0, 200));
  }
  return cleaned.slice(start, end + 1);
};

const tryParse = (raw) => {
  try {
    return JSON.parse(raw);
  } catch (e) {
    const repaired = raw
      .replace(/,\s*([}\]])/g, '$1')
      .replace(/[\u201C\u201D]/g, '"')
      .replace(/[\u2018\u2019]/g, "'");
    return JSON.parse(repaired);
  }
};

const rawJson = extractJSONArray(text);
const books = tryParse(rawJson);
if (!Array.isArray(books)) {
  throw new Error('명문장 추출 결과가 배열이 아닙니다: ' + rawJson.substring(0, 200));
}

return books.map(book => ({
  json: {
    title: book.title,
    author: book.author,
    quote: book.quote,
    category: batch.category,
    batch_index: batch.batchIndex,
    batch_size: batch.batchSize,
  }
}));
